def is_palindrome(string: str) -> bool:     return string == string[::-1]   def make_palindrome(string: str) -> str:     """ Find the shortest palindrome that begins with a supplied string.     Algorithm idea is simple:     - Find the longest postfix of supplied string that is a palindrome.     - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.     >>> make_palindrome('')     ''     >>> make_palindrome('cat')     'catac'     >>> make_palindrome('cata')     'catac'     """
     l = len(string)
     p = string[::-1]
     if p == string:
        return string
     if l <= 1:
        return string
     for i in range(l-1, -1, -1):
        if p[i] == string[l-i-1]:
            return string[:l-i-1] + p[i:]
